import type { CRDocument } from '../types';

export const docs: CRDocument[] = [
  {
    id: "agpeya-prime",
    title: { en: "Prime", ar: "باكر" },
    blocks: [
      { kind: 'note', text: { en: "We pray the First Hour at sunrise, commemorating the Resurrection of our Lord Jesus Christ. At this hour, Christ rose from the dead and appeared to the women at the tomb.", ar: "واحد هو الله أبو كل أحد. واحد هو أيضا ابنه يسوع المسيح الكلمة، الذي تجسد ومات وقام من الأموات في اليوم الثالث وأقامنا معه، واحد هو الروح القدس المعزى الواحد بأقنومه، منبثق من الآب، يطهر كل البرية. يعلمنا أن نسجد للثالوث القدوس بلاهوت واحد وطبيعة واحدة، نسبحه ونباركه إلى الأبد. آمين." } },
      { kind: 'heading', text: { en: "The Introduction to Every Hour", ar: "مقدمة كل ساعة" } },
      { kind: 'prayer', text: { en: "In the name of the Father, and the Son, and the Holy Spirit,", ar: "باسم الآب والابن والروح القدس" } },
      { kind: 'prayer', text: { en: "the one God. Amen.", ar: "الإله الواحد آمين." } },
      { kind: 'prayer', text: { en: "Kyrie eleison. Lord have mercy, Lord have mercy, Lord bless us. Amen.", ar: "يا رب ارحم. يا رب ارحم. يا رب بارك. آمين." } },
      { kind: 'prayer', text: { en: "Glory be to the Father, and to the Son, and to the Holy Spirit, now and forever and unto the ages of ages. Amen.", ar: "المجد للآب والابن والروح القدس الآن وكل أوان وإلى دهر الدهور آمين." } },
      { kind: 'heading', text: { en: "The Beginning of the Prime Prayer", ar: "بدء صلاة باكر" } },
      { kind: 'prayer', text: { en: "The prayer of Prime of the blessed day, I offer to Christ my King and my God, beseeching Him to forgive me my sins.", ar: "صلاة باكر من النهار المبارك، أقدمها للمسيح ملكي وإلهي، وأرجوه أن يغفر لي خطاياي." } },
      { kind: 'heading', text: { en: "Come, Let Us Worship", ar: "هلم نسجد" } },
      { kind: 'hymn', text: { en: "Come, let us worship. Come, let us ask Christ our God. Come, let us worship. Come, let us entreat Christ our King. Come, let us worship. Come, let us plead with Christ our Savior. O our Lord Jesus Christ, the Word of God our God, through the intercessions of Saint Mary and of all Your saints, keep us and grant us a good beginning. Have mercy on us according to Your will forever. The night has passed; we thank You, O Lord, and we ask You to keep us this day without sin, and deliver us.", ar: "هلم نسجد هلم نسأل المسيح إلهنا. هلم نسجد، هلم نطلب من المسيح ملكنا. هلم نسجد، هلم نتضرع إلى المسيح مخلصنا. يا ربنا يسوع المسيح كلمة الله إلهنا، بشفاعة القديسة مريم وجميع قديسيك، احفظنا ولنبدأ بدءا حسنا. ارحمنا كإرادتك إلى الأبد. الليل عبر، نشكرك يا رب ونسأل أن تحفظنا في هذا اليوم بغير خطية وأنقذنا." } },
      { kind: 'heading', text: { en: "Thanksgiving Prayer", ar: "صلاة الشكر" } },
      { kind: 'prayer', text: { en: "Let us give thanks to the beneficent and merciful God, the Father of our Lord, God and Savior, Jesus Christ, for He has covered us, helped us, guarded us, accepted us to Him, had compassion on us, supported us, and has brought us to this hour. Let us also ask Him, the Lord our God, the Pantocrator, to guard us in all peace this holy day and all the days of our life.", ar: "فلنشكر صانع الخيرات الرحوم الله، أبا ربنا وإلهنا ومخلصنا يسوع المسيح، لأنه سترنا وأعاننا، وحفظنا، وقبلنا إليه وأشفق علينا وعضدنا، وأتى بنا إلى هذه الساعة. هو أيضا فلنسأله أن يحفظنا في هذا اليوم المقدس وكل أيام حياتنا بكل سلام. الضابط الكل الرب إلهنا." } },
      { kind: 'prayer', text: { en: "O Master, Lord, God the Pantocrator, the Father of our Lord, God, and Savior, Jesus Christ, we thank You for every condition, concerning every condition, and in every condition. For You have covered us, helped us, guarded us, accepted us to You, had compassion on us, supported us, and brought us to this hour.", ar: "أيها السيد الإله ضابط الكل أبو ربنا وإلهنا ومخلصنا يسوع المسيح، نشكرك على كل حال ومن أجل كل حال، وفى كل حال، لأنك سترتنا، وأعنتنا، وحفظتنا، وقبلتنا إليك، وأشفقت علينا، وعضدتنا، وأتيت بنا إلى هذه الساعة." } },
      { kind: 'prayer', text: { en: "Therefore, we ask and entreat Your goodness, O Lover of Mankind. Grant us to complete this holy day, and all the days of our life, in all peace in Your fear. All envy, all temptation, all the work of Satan, the counsel of wicked men and the rising up of enemies, hidden and manifest, take them away from us and from all Your people and from this holy place that is Yours. But those things which are good and profitable do provide for us. For it is You who have given us the authority to trample on serpents and scorpions, and upon all the power of the enemy.", ar: "من أجل هذا نسأل ونطلب من صلاحك يا محب البشر، امنحنا أن نكمل هذا اليوم المقدس وكل أيام حياتنا بكل سلام مع خوفك. كل حسد، وكل تجربة وكل فعل الشيطان ومؤامرة الناس الأشرار، وقيام الأعداء الخفيين والظاهريين، انزعها عنا وعن سائر شعبك، وعن موضعك المقدس هذا. أما الصالحات والنافعات فارزقنا إياها. لأنك أنت الذي أعطيتنا السلطان أن ندوس الحيات والعقارب وكل قوة العدو. ولا تدخلنا في تجربة، لكن نجنا من الشرير." } },
      { kind: 'prayer', text: { en: "And lead us not into temptation, but deliver us from the evil one, by the grace, compassion and love-of-mankind, of Your only-begotten Son, our Lord, God and Savior, Jesus Christ. Through whom the glory, the honor, the dominion, and the adoration are due unto You, with Him, and the Holy Spirit, the Life-Giver, who is of one essence with You, now and at all times, and unto the age of all ages. Amen.", ar: "بالنعمة والرأفات ومحبة البشر اللواتي لابنك الوحيد ربنا وإلهنا ومخلصنا يسوع المسيح. هذا الذي من قبله المجد والإكرام والعزة والسجود تليق بك معه مع الروح القدس المحيي المساوي لك الآن وكل أوان وإلى دهر الدهور آمين." } },
      { kind: 'rubric', text: { en: "From the Psalms of our father David the prophet and king, may his blessings be upon us all. Amen.", ar: "من مزامير معلمنا داود النبي بركاته علينا أمين." } },
      { kind: 'heading', text: { en: "Psalm 50", ar: "مزمور" } },
      { kind: 'heading', text: { en: "Psalm 1", ar: "مزمور 1" } },
      { kind: 'psalm', text: { en: "Blessed is the man who has not walked in the counsel of the ungodly.", ar: "طوبى للرجل الذي لم يسلك في مشورة المنافقين." }, label: { en: "1", ar: "1" } },
      { kind: 'psalm', text: { en: "And has not stood in the way of the sinners, and has not sat in the seat of the evil men.", ar: "وفى طريق الخطاة لم يقف، وفى مجلس المستهزئين لم يجلس." }, label: { en: "2", ar: "2" } },
      { kind: 'psalm', text: { en: "But his will is in the law of the Lord; and in His law he shall meditate day and night.", ar: "لكن في ناموس الرب إرادته، وفى ناموسه يلهج نهارا وليلا." }, label: { en: "3", ar: "3" } },
      { kind: 'psalm', text: { en: "He shall be like the tree which is planted by the streams of water, which shall yield its fruit in its due season.", ar: "فيكون كالشجرة المغروسة على مجارى المياه التي تعطى ثمرها في حينه." }, label: { en: "4", ar: "4" } },
      { kind: 'psalm', text: { en: "And its leaf shall not scatter, and in everything he does he prospers.", ar: "وورقها لا ينتثر، وكل ما يصنع ينجح فيه." }, label: { en: "5", ar: "5" } },
      { kind: 'psalm', text: { en: "Not so are the ungodly, not so.", ar: "ليس كذلك المنافقون، ليس كذلك." }, label: { en: "6", ar: "6" } },
      { kind: 'psalm', text: { en: "But rather they are like the chaff which the wind scatters upon the face of the earth.", ar: "لكنهم كالهباء الذي تذريه الريح عن وجه الأرض." }, label: { en: "7", ar: "7" } },
      { kind: 'psalm', text: { en: "Therefore the ungodly shall not stand in judgment, nor the sinners in the council of the righteous.", ar: "فلهذا لا يقوم المنافقون في الدينونة، ولا الخطاة في مجمع الصديقين." }, label: { en: "8", ar: "8" } },
      { kind: 'psalm', text: { en: "For the Lord knows the way of the righteous; but the way of the ungodly shall perish.", ar: "لأن الرب يعرف طريق الأبرار، وأما طريق المنافقين فتباد." }, label: { en: "9", ar: "9" } },
      { kind: 'heading', text: { en: "Psalm 2", ar: "مزمور 2" } },
      { kind: 'psalm', text: { en: "Why did the nations rage, and the peoples meditate on vain things?", ar: "لماذا ارتجت الأمم، وتفكرت الشعوب في الباطل." }, label: { en: "1", ar: "1" } },
      { kind: 'psalm', text: { en: "The kings of the earth stood up, and the rulers gathered together against the Lord and against His Christ; saying, \"Let us break through their bonds, and cast away their yoke from us.\"", ar: "قام ملوك الأرض وتآمر الرؤساء معا على الرب وعلى مسيحه قائلين: لنقطع أغلالهما، ولنطرح عنا نيرهما." }, label: { en: "2", ar: "2" } },
      { kind: 'psalm', text: { en: "He who dwells in the heavens shall laugh at them, and the Lord shall mock them.", ar: "الساكن في السموات يضحك بهم، والرب يستهزئ بهم." }, label: { en: "3", ar: "3" } },
      { kind: 'psalm', text: { en: "Then He shall speak to them in His anger, and in His wrath He shall trouble them.", ar: "حينئذ يكلمهم بغضبه، وبرجزه يرجفهم." }, label: { en: "4", ar: "4" } },
      { kind: 'psalm', text: { en: "But I have been established king by Him on Zion, His holy mountain, proclaiming the ordinance of the Lord.", ar: "أنا أقمته ملكا على صهيون جبل قدسه، لأكرز بأمر الرب." }, label: { en: "5", ar: "5" } },
      { kind: 'psalm', text: { en: "The Lord said to Me, \"You are My Son, today I have begotten You.\"", ar: "الرب قال لي: أنت ابني، وأنا اليوم ولدتك." }, label: { en: "6", ar: "6" } },
      { kind: 'psalm', text: { en: "Ask Me, and I will give You the nations for Your inheritance, and Your authority to the end of the earth.", ar: "اسألني فأعطيك الأمم ميراثك، وسلطانك إلى أقطار الأرض." }, label: { en: "7", ar: "7" } },
      { kind: 'psalm', text: { en: "You shall shepherd them with a rod of iron.", ar: "لترعاهم بقضيب من حديد." }, label: { en: "8", ar: "8" } },
      { kind: 'psalm', text: { en: "You shall crush them as a potter's vessel.", ar: "ومثل آنية الفخار تسحقهم." }, label: { en: "9", ar: "9" } },
      { kind: 'psalm', text: { en: "Now, understand, O kings: be instructed, all you who judge the earth, serve the Lord with fear.", ar: "فالآن أيها الملوك افهموا، وتأدبوا يا جميع قضاة الأرض اعبدوا الرب بخشية." }, label: { en: "10", ar: "10" } },
      { kind: 'psalm', text: { en: "And rejoice in Him with trembling.", ar: "وهللوا له برعدة." }, label: { en: "11", ar: "11" } },
      { kind: 'psalm', text: { en: "Take hold of instruction, lest the Lord be angry, and you perish from the way of righteousness.", ar: "الزموا الأدب لئلا يغضب الرب فتضلوا عن طريق الحق." }, label: { en: "12", ar: "12" } },
      { kind: 'psalm', text: { en: "Whenever His wrath shall be suddenly kindled, blessed are all who trust in Him. Alleluia.", ar: "عندما يتقد غضبه بسرعة، طوبى لجميع المتكلين عليه هلليلويا." }, label: { en: "13", ar: "13" } },
      { kind: 'heading', text: { en: "Psalm 3", ar: "مزمور 3" } },
      { kind: 'psalm', text: { en: "O Lord, why have they who afflict me multiplied? Many have risen up upon me.", ar: "يا رب لماذا كثر الذين يحزنونني، كثيرون قاموا علي." }, label: { en: "1", ar: "1" } },
      { kind: 'psalm', text: { en: "Many say unto my soul, \"There is no salvation for him in his God.\"", ar: "كثيرون يقولون لنفسي، ليس له خلاص بإلهه." }, label: { en: "2", ar: "2" } },
      { kind: 'psalm', text: { en: "But You, O Lord, are my supporter, my glory, and the elevation of my head.", ar: "أنت يا رب أنت هو ناصري، مجدي ورافع رأسي." }, label: { en: "3", ar: "3" } },
      { kind: 'psalm', text: { en: "With my voice I cried unto the Lord.", ar: "بصوتي إلى الرب صرخت." }, label: { en: "4", ar: "4" } },
      { kind: 'psalm', text: { en: "And He heard me out of His holy mountain.", ar: "فاستجاب لي من جبل قدسه." }, label: { en: "5", ar: "5" } },
      { kind: 'psalm', text: { en: "I laid down and slept; and I arose; for the Lord is He who supports me.", ar: "أنا اضطجعت ونمت، ثم استيقظت لأن الرب ناصري." }, label: { en: "6", ar: "6" } },
      { kind: 'psalm', text: { en: "I will not be afraid of ten thousands of people, who surround me; who have risen upon me.", ar: "فلا أخاف من ربوات الجموع المحيطين بي القائمين على." }, label: { en: "7", ar: "7" } },
      { kind: 'psalm', text: { en: "Rise, O Lord, save me, O my God: for You have smitten all who are enemies to me without cause.", ar: "قم يا رب خلصني يا إلهي، لأنك ضربت كل من يعاديني باطلا." }, label: { en: "8", ar: "8" } },
      { kind: 'psalm', text: { en: "The teeth of the sinners You have broken.", ar: "أسنان الخطاة سحقتها." }, label: { en: "9", ar: "9" } },
      { kind: 'psalm', text: { en: "Salvation is the Lord's, and His blessing is upon His people.", ar: "للرب الخلاص وعلى شعبه بركته." }, label: { en: "10", ar: "10" } },
      { kind: 'heading', text: { en: "Psalm 4", ar: "مزمور 4" } },
      { kind: 'psalm', text: { en: "When I cried out, God of my righteousness heard me.", ar: "إذ دعوتُ استجبتَ لي يا إله بري." }, label: { en: "1", ar: "1" } },
      { kind: 'psalm', text: { en: "In tribulation You have made room for me.", ar: "في الشدة فرجت عنى." }, label: { en: "2", ar: "2" } },
      { kind: 'psalm', text: { en: "Have compassion upon me, O Lord, and hear my prayer.", ar: "تراءف على يا رب واسمع صلاتي." }, label: { en: "3", ar: "3" } },
      { kind: 'psalm', text: { en: "O you, sons of men, how long will your hearts be heavy? Why do you love vanity, and seek falsehood? Know you that the Lord has made His Holy One wondrous.", ar: "يا بني البشر، حتى متى تثقل قلوبكم؟ لماذا تحبون الباطل وتبتغون الكذب؟ اعلموا أن الرب قد جعل صفيه عجبا." }, label: { en: "4", ar: "4" } },
      { kind: 'psalm', text: { en: "The Lord hears me when I cry to Him.", ar: "الرب يستجيب لي إذا ما صرخت إليه." }, label: { en: "5", ar: "5" } },
      { kind: 'psalm', text: { en: "Be angry, and do not sin; feel sorrow upon your beds for what you say in your hearts.", ar: "اغضبوا ولا تخطئوا، الذي تقولونه في قلوبكم اندموا عليه في مضاجعكم." }, label: { en: "6", ar: "6" } },
      { kind: 'psalm', text: { en: "Offer the sacrifice of righteousness, and trust in the Lord.", ar: "اذبحوا ذبيحة البر، وتوكلوا على الرب." }, label: { en: "7", ar: "7" } },
      { kind: 'psalm', text: { en: "Many say, \"Who can show us the good things?\" The light of Your countenance, O Lord, has been shined upon us.", ar: "كثيرون يقولون: من يرينا الخيرات؟ قد أضاء علينا نور وجهك يا رب." }, label: { en: "8", ar: "8" } },
      { kind: 'psalm', text: { en: "You have given gladness to my heart: they have been multiplied with the fruit of their wheat and wine and oil.", ar: "أعطيت سرورا لقلبي أوفر من الذين كثرت حنطتهم وخمرهم وزيتهم." }, label: { en: "9", ar: "9" } },
      { kind: 'psalm', text: { en: "I shall both lie down in peace and sleep: for You alone, O Lord, have caused me to dwell in hope. Alleluia.", ar: "فبالسلامة أضطجع أيضا وأنام، لأنك أنت وحدك يا رب أسكنتني على الرجاء هلليلويا." }, label: { en: "10", ar: "10" } },
      { kind: 'heading', text: { en: "Psalm 5", ar: "مزمور 5" } },
      { kind: 'psalm', text: { en: "Hearken, O Lord, to my words and consider my cry.", ar: "أنصت يا رب لكلماتي، واسمع صراخي." }, label: { en: "1", ar: "1" } },
      { kind: 'psalm', text: { en: "Observe the voice of my supplication, my King, and my God: for to You, O Lord, I will pray.", ar: "أصغ إلى صوت طلبتي يا ملكي وإلهي، لأني إليك أصلى." }, label: { en: "2", ar: "2" } },
      { kind: 'psalm', text: { en: "In the morning You shall hear my voice: in the early morning I shall stand before You, and You will look upon me.", ar: "يا رب بالغداة تسمع صوتي، بالغداة أقف أمامك وتراني." }, label: { en: "3", ar: "3" } },
      { kind: 'psalm', text: { en: "For You are not a God who desires iniquity; nor shall he who works evil dwell in You.", ar: "لأنك إله لا تشاء الإثم، ولا يساكنك من يصنع الشر." }, label: { en: "4", ar: "4" } },
      { kind: 'psalm', text: { en: "Nor shall the transgressors abide before Your eyes.", ar: "ولا يثبت مخالفو الناموس أمام عينيك." }, label: { en: "5", ar: "5" } },
      { kind: 'psalm', text: { en: "You have hated, O Lord, all who work iniquity. You will destroy all who speak falsehood.", ar: "يا رب أبغضت جميع فاعلي الإثم، وتهلك كل الناطقين بالكذب." }, label: { en: "6", ar: "6" } },
      { kind: 'psalm', text: { en: "A man of blood and deceit the Lord abhors.", ar: "رجل الدماء والغاش يرذله الرب." }, label: { en: "7", ar: "7" } },
      { kind: 'psalm', text: { en: "But as for me, according to the multitude of Your mercy I shall enter Your house: I shall worship before Your holy temple in Your fear.", ar: "أما أنا فبكثرة رحمتك أدخل بيتك، وأسجد قدام هيكل قدسك بمخافتك." }, label: { en: "8", ar: "8" } },
      { kind: 'psalm', text: { en: "Guide me, O Lord, in Your righteousness.", ar: "اهدني يا رب ببرك." }, label: { en: "9", ar: "9" } },
      { kind: 'psalm', text: { en: "For the sake of my enemies, make my way straight before You.", ar: "من أجل أعدائي سهل أمامي طريقك." }, label: { en: "10", ar: "10" } },
      { kind: 'psalm', text: { en: "For in their mouth there is no truth.", ar: "لأن ليس في أفواههم صدق." }, label: { en: "11", ar: "11" } },
      { kind: 'psalm', text: { en: "Their heart is vain.", ar: "باطل هو قلبهم." }, label: { en: "12", ar: "12" } },
      { kind: 'psalm', text: { en: "Their throat is an open tomb.", ar: "حنجرتهم قبر مفتوح." }, label: { en: "13", ar: "13" } },
      { kind: 'psalm', text: { en: "With their tongues they have done deceit.", ar: "وبألسنتهم قد غشوا." }, label: { en: "14", ar: "14" } },
      { kind: 'psalm', text: { en: "Judge them, O God.", ar: "فدنهم يا لله." }, label: { en: "15", ar: "15" } },
      { kind: 'psalm', text: { en: "Let them fall down in all their counsels: wipe them out according to the abundance of their ungodliness; for they have provoked You, O Lord.", ar: "وليسقطوا من جميع مؤامراتهم وككثرة نفاقهم استأصلهم، لأنهم قد أغضبوك يا رب." }, label: { en: "16", ar: "16" } },
      { kind: 'psalm', text: { en: "But let all who hope in You be glad: they shall rejoice for ever, and You shall dwell in them.", ar: "وليفرح جميع المتكلين عليك، إلى الأبد يسرون وتحل فيهم." }, label: { en: "17", ar: "17" } },
      { kind: 'psalm', text: { en: "And all who love Your name shall be proud in You.", ar: "ويفتخر بك كل الذين يحبون اسمك." }, label: { en: "18", ar: "18" } },
      { kind: 'psalm', text: { en: "For You, O Lord, have blessed the righteous.", ar: "لأنك أنت باركت الصديق يا رب." }, label: { en: "19", ar: "19" } },
      { kind: 'psalm', text: { en: "As a shield of favor You have crowned us.", ar: "كما بترس المسرة كللتنا." }, label: { en: "20", ar: "20" } },
      { kind: 'heading', text: { en: "Psalm 6", ar: "مزمور 6" } },
      { kind: 'psalm', text: { en: "O Lord, do not rebuke me in Your anger, nor chasten me in Your wrath.", ar: "يا رب لا تبكتني بغضبك، ولا تؤدبني بسخطك." }, label: { en: "1", ar: "1" } },
      { kind: 'psalm', text: { en: "Have mercy on me, O Lord; for I am weak: heal me, O Lord, for my bones are troubled, and my soul is grievously troubled.", ar: "ارحمني يا رب فإني ضعيف، اشفني يا رب فإن عظامي قد اضطربت ونفسي قد انزعجت جدا." }, label: { en: "2", ar: "2" } },
      { kind: 'psalm', text: { en: "But You, O Lord, how long? Return, deliver my soul: revive me for the sake of Your mercy.", ar: "وأنت يا رب فإلي متى؟ عد ونج نفسي، وأحيني من أجل رحمتك." }, label: { en: "3", ar: "3" } },
      { kind: 'psalm', text: { en: "For in death there is no one who is remembering You: and in Hades who is able to confess to You?", ar: "لأنه ليس في الموت من يذكرك ولا في الجحيم من يعترف لك." }, label: { en: "4", ar: "4" } },
      { kind: 'psalm', text: { en: "I became wearied in my groaning.", ar: "تعبت في تنهدي." }, label: { en: "5", ar: "5" } },
      { kind: 'psalm', text: { en: "I shall wash my bed every night; I shall wet my couch with my tears.", ar: "أعوم كل ليلة سريري، وبدموعي أبل فراشي." }, label: { en: "6", ar: "6" } },
      { kind: 'psalm', text: { en: "My eye is troubled because of anger.", ar: "تعكرت من الغضب عيناي." }, label: { en: "7", ar: "7" } },
      { kind: 'psalm', text: { en: "I have grown old because of all my enemies.", ar: "شاخت من سائر أعدائي ." }, label: { en: "8", ar: "8" } },
      { kind: 'psalm', text: { en: "Depart away from me, all who do iniquity.", ar: "ابعدوا عنى يا جميع فاعلي الإثم." }, label: { en: "9", ar: "9" } },
      { kind: 'psalm', text: { en: "For the Lord has heard the voice of my weeping.", ar: "لأن الرب قد سمع صوت بكائي." }, label: { en: "10", ar: "10" } },
      { kind: 'psalm', text: { en: "The Lord has heard my petition; the Lord has accepted my prayer. All my enemies shall be put to shame and greatly troubled: they shall be turned back and put to shame speedily.", ar: "الرب سمع تضرعي، الرب لصلاتي قبل، فليَخزَ وليضطرب جدا جميع أعدائي، وليرتدوا إلى ورائهم بالخزي سريعا جدا." }, label: { en: "11", ar: "11" } },
      { kind: 'heading', text: { en: "Psalm 8", ar: "مزمور 8" } },
      { kind: 'psalm', text: { en: "O Lord, our Lord, how wonderful Your name became in all the earth!", ar: "أيها الرب ربنا، ما أعجب اسمك في الأرض كلها!" }, label: { en: "1", ar: "1" } },
      { kind: 'psalm', text: { en: "For the greatness of Your splendor has been exalted above the heavens.", ar: "لأنه قد ارتفع عظم جلالك فوق السموات." }, label: { en: "2", ar: "2" } },
      { kind: 'psalm', text: { en: "Out of the mouth of babes and sucklings You have prepared praise, because of Your enemies, that You might put down an enemy and avenger.", ar: "من أفواه الأطفال والرضعان هيأت سبحا، من أجل أعدائك، لتسكت عدوا ومنتقما." }, label: { en: "3", ar: "3" } },
      { kind: 'psalm', text: { en: "For I will regard the heavens, the work of Your fingers.", ar: "لأني أرى السموات أعمال أصابعك." }, label: { en: "4", ar: "4" } },
      { kind: 'psalm', text: { en: "The moon and stars You have established.", ar: "القمر والنجوم أنت أسستها." }, label: { en: "5", ar: "5" } },
      { kind: 'psalm', text: { en: "What is man, that You have been mindful of him? Or the son of man, that You have visited him?", ar: "من هو الإنسان حتى تذكره، أو ابن الإنسان حتى تفتقده؟!" }, label: { en: "6", ar: "6" } },
      { kind: 'psalm', text: { en: "You made him a little less than angels.", ar: "أنقصته قليلا عن الملائكة." }, label: { en: "7", ar: "7" } },
      { kind: 'psalm', text: { en: "You have crowned him with glory and honor; and You have set him upon the works of Your hands.", ar: "بالمجد والكرامة توجته، وعلى أعمال يديك أقمته." }, label: { en: "8", ar: "8" } },
      { kind: 'psalm', text: { en: "You have put everything under his feet: all the sheep and oxen, and the beasts of the field, and the birds of the sky, and the fish of the sea that pass through the paths of the seas.", ar: "كل شيء أخضعت تحت قدميه، الغنم والبقر جميعا وأيضا بهائم الحقل، وطيور السماء وأسماك البحر السالكة في البحار." }, label: { en: "9", ar: "9" } },
      { kind: 'psalm', text: { en: "O Lord our Lord.", ar: "أيها الرب ربنا." }, label: { en: "10", ar: "10" } },
      { kind: 'psalm', text: { en: "How wonderful Your name became in all the earth!", ar: "ما أعجب اسمك في الأرض كلها." }, label: { en: "11", ar: "11" } },
      { kind: 'heading', text: { en: "Psalm 11", ar: "مزمور 11" } },
      { kind: 'psalm', text: { en: "Save me O Lord, for the godly one has ceased; and the truths have diminished from the children of men.", ar: "خلصني يا رب فإن البار قد فني، وقد قلت الأمانة من بنى البشر." }, label: { en: "1", ar: "1" } },
      { kind: 'psalm', text: { en: "Every one has spoken vanities to his friend.", ar: "تكلم كل واحد مع قريبه بالأباطيل." }, label: { en: "2", ar: "2" } },
      { kind: 'psalm', text: { en: "Deceiving lips are in their hearts, and thus they have spoken with their hearts.", ar: "شفاه غاشة في قلوبهم وبقلوبهم تخاطبوا." }, label: { en: "3", ar: "3" } },
      { kind: 'psalm', text: { en: "The Lord shall wipe out every deceiving lip, and every tongue that speaks great words.", ar: "يستأصل الرب جميع الشفاه الغاشة، واللسانَ الناطق بالعظائم." }, label: { en: "4", ar: "4" } },
      { kind: 'psalm', text: { en: "Those who have said, \"We will magnify our tongues; our lips are our own: who is lord over us?\"", ar: "الذين قالوا: نعظم ألسنتنا شفاهنا معنا، فمن هو رب علينا؟!" }, label: { en: "5", ar: "5" } },
      { kind: 'psalm', text: { en: "\"Because of the misery of the poor and the sighing of the oppressed, now I will rise,\" says the Lord, \"I will set them in salvation, and I will be revealed in it.\"", ar: "من أجل شقاء المساكين وتنهد البائسين الآن أقوم، يقول الرب، أصنع الخلاص علانية." }, label: { en: "6", ar: "6" } },
      { kind: 'psalm', text: { en: "The words of the Lord are pure words; as silver tried in the fire, proved in the earth, purified seven times.", ar: "كلام الرب كلام نقي، فضة محماة مجربة في الأرض، قد صفيت سبعة أضعاف." }, label: { en: "7", ar: "7" } },
      { kind: 'psalm', text: { en: "You, O Lord, shall keep us, and shall preserve us from this generation, and forever.", ar: "وأنت يا رب تنجينا وتحفظنا من هذا الجيل وإلى الدهر." }, label: { en: "8", ar: "8" } },
      { kind: 'psalm', text: { en: "The ungodly walk around.", ar: "المنافقون حولنا يمشون." }, label: { en: "9", ar: "9" } },
      { kind: 'psalm', text: { en: "According to Your greatness You have prolonged the lives of the children of men.", ar: "مثل ارتفاعك أكثرت أعمار بنى البشر." }, label: { en: "10", ar: "10" } },
      { kind: 'heading', text: { en: "Psalm 12", ar: "مزمور 12" } },
      { kind: 'psalm', text: { en: "How long, O Lord, do You forget me, for ever? How long do You turn Your face away from me? How long do I put these counsels in my soul, and these sorrows in my heart for the whole day? How long does my enemy exalt over me? Look, hearken to me, O Lord my God.", ar: "إلى متى يا رب تنساني؟ إلى الانقضاء؟ حتى متى تصرف وجهك عنى؟ إلى متى أردد هذه المشورات في نفسي، وهذه الأوجاع في قلبي النهار كله؟ إلى متى يرتفع عدوى علي؟ انظر واستجب لي يا ربي وإلهي." }, label: { en: "1", ar: "1" } },
      { kind: 'psalm', text: { en: "Enlighten my eyes, lest I sleep in death; lest my enemy say, \"I have prevailed against him.\"", ar: "أنر عيني لئلا أنام نوم الموت، لئلا يقول عدوي: إني قد قويت عليه." }, label: { en: "2", ar: "2" } },
      { kind: 'psalm', text: { en: "Those who distress me will rejoice if ever I stumble.", ar: "الذين يحزنونني يتهللون إن أنا زللت." }, label: { en: "3", ar: "3" } },
      { kind: 'psalm', text: { en: "But I have hoped in Your mercy.", ar: "أما أنا فعلى رحمتك توكلت." }, label: { en: "4", ar: "4" } },
      { kind: 'psalm', text: { en: "My heart will rejoice in Your salvation.", ar: "يبتهج قلبي بخلاصك." }, label: { en: "5", ar: "5" } },
      { kind: 'psalm', text: { en: "I will praise the Lord Who has done good to me, and I will sing to the name of the Lord Most High.", ar: "أسبح الرب المحسنَ إلي، وأرتل لاسم الرب العلي." }, label: { en: "6", ar: "6" } },
      { kind: 'heading', text: { en: "Psalm 14", ar: "مزمور 14" } },
      { kind: 'psalm', text: { en: "O Lord, who shall abide in Your dwelling place? And who can rest upon Your holy mountain? It is he who walks blamelessly, doing righteousness, speaking truth in his heart, he who has not spoken deceitfully with his tongue, neither has done evil to his friend, nor taking up a reproach against his neighbors.", ar: "يا رب من يسكن في مسكنك، ومن يحل في جبل قدسك؟ السالك بلا عيب والفاعل البر، والمتكلم بالحق في قلبه، الذي لا يغش بلسانه، ولا يصنع بقريبه سوءا، ولا يقبل عارا على جيرانه." }, label: { en: "1", ar: "1" } },
      { kind: 'psalm', text: { en: "The evil worker is disdained before him, but he glorifies those who fear the Lord.", ar: "فاعل الشر مرذول أمامه، ويمجد الذين يتقون الرب." }, label: { en: "2", ar: "2" } },
      { kind: 'psalm', text: { en: "He gives oath to his friend and does not turn away from him.", ar: "الذي يحلف لقريبه ولا يغدر به." }, label: { en: "3", ar: "3" } },
      { kind: 'psalm', text: { en: "He has not given his money on usury, and has not received bribes against the godly.", ar: "ولا يعطى فضته بالربا، ولا يقبل الرشوة على الأبرياء." }, label: { en: "4", ar: "4" } },
      { kind: 'psalm', text: { en: "He who does these things shall not stumble forever.", ar: "الذي يصنع هذا لا يتزعزع إلى الأبد." }, label: { en: "5", ar: "5" } },
      { kind: 'heading', text: { en: "Psalm 15", ar: "مزمور 15" } },
      { kind: 'psalm', text: { en: "Keep me, O Lord; for I have hoped in You.", ar: "احفظني يا رب فإني عليك توكلت." }, label: { en: "1", ar: "1" } },
      { kind: 'psalm', text: { en: "I said to the Lord, \"You are my Lord, and You have no need of my goodness.\"", ar: "قلت للرب: أنت ربي، ولا تحتاج إلى صلاحي." }, label: { en: "2", ar: "2" } },
      { kind: 'psalm', text: { en: "He has manifested His wonders to His saints who are in His earth, and He has wrought all His desires in them.", ar: "أظهر عجائبه لقديسيه الذين في أرضه، وصنع فيهم كل مشيئاته." }, label: { en: "3", ar: "3" } },
      { kind: 'psalm', text: { en: "Their ailments have been multiplied who hastened after another God.", ar: "كثرت أمراضهم الذين أسرعوا وراء آخر." }, label: { en: "4", ar: "4" } },
      { kind: 'psalm', text: { en: "I will not assemble their meetings of blood, nor make mention of their names with my lips.", ar: "لا أجمع مجامعهم من الدماء، ولا أذكر أسماءهم بشفتي." }, label: { en: "5", ar: "5" } },
      { kind: 'psalm', text: { en: "The Lord is the portion of my inheritance and my cup.", ar: "الرب هو نصيب ميراثي وكأسي." }, label: { en: "6", ar: "6" } },
      { kind: 'psalm', text: { en: "You are He who brings my inheritance back to me.", ar: "أنت الذي ترد إلى ميراثي." }, label: { en: "7", ar: "7" } },
      { kind: 'psalm', text: { en: "The measuring lines have fallen to me among the best, and my inheritance is confirmed for me.", ar: "حبال المساحة وقعت لي في أرض خصبة، وإن ميراثي لثابت لي." }, label: { en: "8", ar: "8" } },
      { kind: 'psalm', text: { en: "I will bless the Lord who has given me understanding.", ar: "أبارك الرب الذي أفهمني." }, label: { en: "9", ar: "9" } },
      { kind: 'psalm', text: { en: "My reins too have instructed me even till the night.", ar: "وأيضا إلى الليل تنذرني كليتاي." }, label: { en: "10", ar: "10" } },
      { kind: 'psalm', text: { en: "I foresaw the Lord always before me; He is on my right hand, that I should not be moved.", ar: "تقدمت فرأيت الرب أمامي في كل حين، لأنه عن يميني لكي لا أتزعزع." }, label: { en: "11", ar: "11" } },
      { kind: 'psalm', text: { en: "Therefore my heart rejoiced and my tongue exulted.", ar: "من أجل هذا فرح قلبي وتهلل لساني." }, label: { en: "12", ar: "12" } },
      { kind: 'psalm', text: { en: "Moreover also my flesh shall live in hope.", ar: "وأيضا جسدي يسكن على الرجاء." }, label: { en: "13", ar: "13" } },
      { kind: 'psalm', text: { en: "Because You shall not leave my soul in Hades.", ar: "لأنك لا تترك نفسي في الجحيم." }, label: { en: "14", ar: "14" } },
      { kind: 'psalm', text: { en: "Neither shall You suffer Your Holy One to see corruption.", ar: "ولا تدع قدوسك يرى فسادا." }, label: { en: "15", ar: "15" } },
      { kind: 'psalm', text: { en: "You have made known to me the ways of life.", ar: "قد عرفتني سبل الحياة." }, label: { en: "16", ar: "16" } },
      { kind: 'psalm', text: { en: "You will fill me with joy with Your face.", ar: "تملأني فرحا مع وجهك." }, label: { en: "17", ar: "17" } },
      { kind: 'psalm', text: { en: "Delight is in Your right hand forever.", ar: "البهجة في يمينك إلى الانقضاء." }, label: { en: "18", ar: "18" } },
      { kind: 'heading', text: { en: "Psalm 18", ar: "مزمور 18" } },
      { kind: 'psalm', text: { en: "The heavens declare the glory of God; and the firmament proclaims the work of His hands.", ar: "السموات تحدث بمجد الله، والفلك يخبر بعمل يديه." }, label: { en: "1", ar: "1" } },
      { kind: 'psalm', text: { en: "Day to day utters speech.", ar: "يوم إلى يوم يبدي قولا." }, label: { en: "2", ar: "2" } },
      { kind: 'psalm', text: { en: "And night to night proclaims knowledge.", ar: "وليل إلى ليل يظهر علما." }, label: { en: "3", ar: "3" } },
      { kind: 'psalm', text: { en: "There are no speeches or words.", ar: "لا قول ولا كلام." }, label: { en: "4", ar: "4" } },
      { kind: 'psalm', text: { en: "In which their voice is not heard. Their sound has gone out upon all the earth.", ar: "لا تسمع أصواتهم، في كل الأرض خرج منطقهم." }, label: { en: "5", ar: "5" } },
      { kind: 'psalm', text: { en: "And their words have reached to the ends of the world.", ar: "وإلى أقصى المسكونة بلغت أقوالهم." }, label: { en: "6", ar: "6" } },
      { kind: 'psalm', text: { en: "In the sun He has set His dwelling.", ar: "جعل في الشمس مظلته." }, label: { en: "7", ar: "7" } },
      { kind: 'psalm', text: { en: "And it comes forth as a bridegroom out of his chamber.", ar: "وهى مثل العريس الخارج من خدره." }, label: { en: "8", ar: "8" } },
      { kind: 'psalm', text: { en: "It shall exult as a giant running his course.", ar: "تتهلل مثل الجبار الذي يسرع في طريقه." }, label: { en: "9", ar: "9" } },
      { kind: 'psalm', text: { en: "Its going forth is from the extremity of heaven, and its goal is to the other end of heaven: and nothing will be hidden from its heat.", ar: "من أقصى السماء خروجها، ومنتهاها إلى أقصى السماء ولا شيء يختفي من حرارتها." }, label: { en: "10", ar: "10" } },
      { kind: 'psalm', text: { en: "The law of the Lord is pure, converting souls.", ar: "ناموس الرب بلا عيب، يرد النفوس." }, label: { en: "11", ar: "11" } },
      { kind: 'psalm', text: { en: "The testimony of the Lord is faithful, instructing the babes.", ar: "شهادة الرب صادقة، تعلم الأطفال." }, label: { en: "12", ar: "12" } },
      { kind: 'psalm', text: { en: "The ordinances of the Lord are straight, rejoicing the heart.", ar: "فرائض الرب مستقيمة، تفرح القلب." }, label: { en: "13", ar: "13" } },
      { kind: 'psalm', text: { en: "The commandment of the Lord is a light, enlightening the eyes from afar.", ar: "وصية الرب مضيئة، تنير العينين عن بعد." }, label: { en: "14", ar: "14" } },
      { kind: 'psalm', text: { en: "The fear of the Lord is pure, enduring forever and ever.", ar: "خشية الرب زكية، دائمة إلى أبد الأبد." }, label: { en: "15", ar: "15" } },
      { kind: 'psalm', text: { en: "The judgements of the Lord are true, and justified altogether.", ar: "أحكام الرب أحكام حق وعادلة معا." }, label: { en: "16", ar: "16" } },
      { kind: 'psalm', text: { en: "The desires of His heart are chosen.", ar: "شهوة قلبه مختارة." }, label: { en: "17", ar: "17" } },
      { kind: 'psalm', text: { en: "More than gold and precious stone, and sweeter than honey and the honey-comb.", ar: "أفضل من الذهب والحجر الكثير الثمن، وأحلى من العسل والشهد." }, label: { en: "18", ar: "18" } },
      { kind: 'psalm', text: { en: "For Your servant keeps them: and in keeping them there is great reward.", ar: "عبدك يحفظها، وفى حفظها ثواب عظيم." }, label: { en: "19", ar: "19" } },
      { kind: 'psalm', text: { en: "Who can understand transgressions? From my secret sins cleanse me, O Lord, and from the attack of strangers spare Your servant: if they do not have dominion over me, then I shall be blameless, and I shall be cleansed from great sin.", ar: "الهفوات من يشعر بها؟ من الخطايا المستترة يا رب طهرني، ومن الغرباء احفظ عبدك حتى لا يتسلطوا على، فحينئذ أكون بلا عيب، وأتنقى من خطية عظيمة." }, label: { en: "20", ar: "20" } },
      { kind: 'psalm', text: { en: "All the sayings of my mouth, and the meditation of my heart, shall be pleasing continually before You.", ar: "وتكون جميع أقوال فمي وفكر قلبي مرضية أمامك في كل حين." }, label: { en: "21", ar: "21" } },
      { kind: 'psalm', text: { en: "O Lord, You are my helper, and my Savior.", ar: "يا رب أنت معيني ومخلصي." }, label: { en: "22", ar: "22" } },
      { kind: 'heading', text: { en: "Psalm 24", ar: "مزمور 24" } },
      { kind: 'psalm', text: { en: "To You, O Lord, I have lifted up my soul. O my God, I have trusted in You.", ar: "إليك يا رب رفعت نفسي، يا إلهي عليك توكلت." }, label: { en: "1", ar: "1" } },
      { kind: 'psalm', text: { en: "Let me not be ashamed forever, nor let my enemies mock me.", ar: "فلا تخزني إلى الأبد، ولا تشْمت بي أعدائي." }, label: { en: "2", ar: "2" } },
      { kind: 'psalm', text: { en: "For all who wait for You shall not be ashamed.", ar: "لأن جميع الذين ينتظرونك لا يخزون." }, label: { en: "3", ar: "3" } },
      { kind: 'psalm', text: { en: "Let them be ashamed who wrought iniquity in vain.", ar: "ليخز الذين يصنعون الإثم باطلا." }, label: { en: "4", ar: "4" } },
      { kind: 'psalm', text: { en: "Show me Your ways, O Lord; and teach me Your paths.", ar: "أظهر لي يا رب طرقك، وعلمني سبلك." }, label: { en: "5", ar: "5" } },
      { kind: 'psalm', text: { en: "Lead me to Your truth, and teach me.", ar: "اهدني إلى عدلك وعلمني." }, label: { en: "6", ar: "6" } },
      { kind: 'psalm', text: { en: "For You are God my Savior: and for You I have waited the whole day.", ar: "لأنك أنت هو الله مخلصي، وإياك انتظرت النهار كله." }, label: { en: "7", ar: "7" } },
      { kind: 'psalm', text: { en: "Remember, O Lord, Your compassions and Your mercies, for they exist from everlasting.", ar: "اذكر يا رب رأفاتك ومراحمك، لأنها ثابتة منذ الأزل." }, label: { en: "8", ar: "8" } },
      { kind: 'psalm', text: { en: "The sins of my youth and those of my ignorance do not remember.", ar: "خطايا شبابي وجهالاتي لا تذكر." }, label: { en: "9", ar: "9" } },
      { kind: 'psalm', text: { en: "According to Your mercy remember me, for the sake of Your goodness, O Lord.", ar: "كرحمتك اذكرني أنت من أجل صلاحك يا رب." }, label: { en: "10", ar: "10" } },
      { kind: 'psalm', text: { en: "For good and upright is the Lord: therefore He shall set a law for those who sin in the way.", ar: "الرب صالح ومستقيم، لذلك يرشد الذين يخطئون في الطريق." }, label: { en: "11", ar: "11" } },
      { kind: 'psalm', text: { en: "He shall guide the meek in judgment. He shall teach the meek His ways.", ar: "يهدى الودعاء في الحكم، يعلم الودعاء طرقه." }, label: { en: "12", ar: "12" } },
      { kind: 'psalm', text: { en: "All the ways of the Lord are mercy and truth to those who keep His covenant and His testimonies.", ar: "جميع طرق الرب رحمة وحق لحافظي عهده وشهاداته." }, label: { en: "13", ar: "13" } },
      { kind: 'psalm', text: { en: "For the sake of Your name, O Lord, You shall forgive my sin; for it is great.", ar: "من أجل اسمك يا رب اغفر لي خطيتي لأنها كثيرة." }, label: { en: "14", ar: "14" } },
      { kind: 'psalm', text: { en: "Who is the man that fears the Lord? He shall set a law for him in the way which pleases Him.", ar: "من هو الإنسان الخائف الرب، يرشده في الطريق التي ارتضاها." }, label: { en: "15", ar: "15" } },
      { kind: 'psalm', text: { en: "His soul shall dwell in good things; and his seed shall inherit the earth.", ar: "نفسه في الخيرات تثبت، ونسله يرث الأرض." }, label: { en: "16", ar: "16" } },
      { kind: 'psalm', text: { en: "The Lord is the strength of those who fear Him; and the name of the Lord is for those who revere Him.", ar: "الرب عز لخائفيه، واسم الرب لأتقيائه." }, label: { en: "17", ar: "17" } },
      { kind: 'psalm', text: { en: "And His covenant He will manifest to them.", ar: "ولهم يعلن عهده." }, label: { en: "18", ar: "18" } },
      { kind: 'psalm', text: { en: "My eyes are ever looking towards the Lord; for He will draw my feet out of the snare.", ar: "عيناي تنظران إلى الرب في كل حين، لأنه يجتذب من الفخ رجلي." }, label: { en: "19", ar: "19" } },
      { kind: 'psalm', text: { en: "Look upon me, and have mercy on me; for I am an only child and poor.", ar: "انظر إلى وارحمني، لأني ابن وحيد وفقير أنا." }, label: { en: "20", ar: "20" } },
      { kind: 'psalm', text: { en: "The afflictions of my heart have been multiplied; bring me out of my troubles.", ar: "أحزان قلبي قد كثرت، أخرجني من شدائدي." }, label: { en: "21", ar: "21" } },
      { kind: 'psalm', text: { en: "Behold my lowliness and my toil.", ar: "انظر إلى ذلي وتعبي." }, label: { en: "22", ar: "22" } },
      { kind: 'psalm', text: { en: "And forgive all my sins.", ar: "واغفر لي جميع خطاياي." }, label: { en: "23", ar: "23" } },
      { kind: 'psalm', text: { en: "Look upon my enemies; for they have multiplied; and they have hated me with an unjust hatred.", ar: "انظر إلى أعدائي فإنهم قد كثروا وأبغضوني ظلما." }, label: { en: "24", ar: "24" } },
      { kind: 'psalm', text: { en: "Keep my soul, and deliver me: let me not be put to shame; for I have hoped in You.", ar: "احفظ نفسي ونجني، لا أخزى لأني عليك توكلت." }, label: { en: "25", ar: "25" } },
      { kind: 'psalm', text: { en: "The harmless and upright joined themselves to me: for I waited for You, O Lord.", ar: "الذين لا شر فيهم والمستقيمون لصقوا بي، لأني انتظرتك يا رب." }, label: { en: "26", ar: "26" } },
      { kind: 'psalm', text: { en: "Deliver Israel, O God, out of all his afflictions.", ar: "يا الله أنقذ إسرائيل من جميع شدائده." }, label: { en: "27", ar: "27" } },
      { kind: 'heading', text: { en: "Psalm 26", ar: "مزمور 26" } },
      { kind: 'psalm', text: { en: "The Lord is my light and my salvation; whom will I fear?", ar: "الرب نوري وخلاصي ممن أخاف؟!" }, label: { en: "1", ar: "1" } },
      { kind: 'psalm', text: { en: "The Lord is the defender of my life; of whom will I be afraid?", ar: "الرب حصن حياتي ممن أجزع؟!" }, label: { en: "2", ar: "2" } },
      { kind: 'psalm', text: { en: "When the wicked drew near against me to eat up my flesh, those who distress me and my enemies, they fainted and fell.", ar: "عندما يقترب الأشرار منى ليأكلوا لحمي، مضايقي وأعدائي عثروا وسقطوا." }, label: { en: "3", ar: "3" } },
      { kind: 'psalm', text: { en: "Though an army should fight me, my heart shall not be afraid.", ar: "إن يحاربني جيش فلن يخاف قلبي." }, label: { en: "4", ar: "4" } },
      { kind: 'psalm', text: { en: "Though war should rise up against me, in this I am confident.", ar: "وإن قام على قتال ففي هذا أنا أطمئن." }, label: { en: "5", ar: "5" } },
      { kind: 'psalm', text: { en: "One thing I have asked of the Lord, this also I will seek.", ar: "واحدة سألت من الرب وإياها ألتمس." }, label: { en: "6", ar: "6" } },
      { kind: 'psalm', text: { en: "That I should dwell in the house of the Lord all the days of my life.", ar: "أن أسكن في بيت الرب كلَّ أيام حياتي." }, label: { en: "7", ar: "7" } },
      { kind: 'psalm', text: { en: "That I should behold the fair beauty of the Lord, and visit His holy temple.", ar: "لكي أنظر نعيم الرب، وأتفرس في هيكله المقدس." }, label: { en: "8", ar: "8" } },
      { kind: 'psalm', text: { en: "For He hid me in His tabernacle.", ar: "لأنه أخفاني في خيمته." }, label: { en: "9", ar: "9" } },
      { kind: 'psalm', text: { en: "In the day of my afflictions He sheltered me in the secret of His tabernacle.", ar: "في يوم شدتي، سترني بستر مظلته." }, label: { en: "10", ar: "10" } },
      { kind: 'psalm', text: { en: "He set me up on a rock.", ar: "وعلى صخرة رفعني." }, label: { en: "11", ar: "11" } },
      { kind: 'psalm', text: { en: "And now, behold, He has lifted up my head over my enemies.", ar: "والآن هوذا قد رفع رأسي على أعدائي." }, label: { en: "12", ar: "12" } },
      { kind: 'psalm', text: { en: "I went round and offered in His tabernacle a sacrifice of joy; I shall sing, and sing psalms to the Lord.", ar: "طفت وذبحت في مظلته ذبيحة التهليل، أسبح وأرتل للرب." }, label: { en: "13", ar: "13" } },
      { kind: 'psalm', text: { en: "Hear, O Lord, my voice which I have uttered aloud.", ar: "استمع يا رب صوتي الذي به دعوتك." }, label: { en: "14", ar: "14" } },
      { kind: 'psalm', text: { en: "Have mercy on me, and hearken to me. For You are He to whom my heart said, \"I have sought Your face: Your face, O Lord, I will seek.\"", ar: "ارحمني واستجب لي فإنه لك قال قلبي: طلبت وجهك، ووجهك يا رب ألتمس." }, label: { en: "15", ar: "15" } },
      { kind: 'psalm', text: { en: "Do not turn away Your face from me, do not reject Your servant in anger.", ar: "لا تحجب وجهك عنى، ولا تنبذ بغضبك عبدك." }, label: { en: "16", ar: "16" } },
      { kind: 'psalm', text: { en: "Be a helper to me, and do not forsake me; and do not overlook me, O God my Savior.", ar: "كن لي معينا، لا تخذلني ولا ترفضني يا الله مخلصي." }, label: { en: "17", ar: "17" } },
      { kind: 'psalm', text: { en: "For my father and my mother have forsaken me, but the Lord has accepted me unto Himself.", ar: "فإن أبى وأمي قد تركاني، وأما الرب فقبلني." }, label: { en: "18", ar: "18" } },
      { kind: 'psalm', text: { en: "Set a law for me, O Lord, in Your ways, and guide me in a right path, because of my enemies.", ar: "علمني يا رب طريقك، واهدني في سبيل مستقيم من أجل أعدائي." }, label: { en: "19", ar: "19" } },
      { kind: 'psalm', text: { en: "Do not deliver me over to the souls of those who afflict me; for unjust witnesses have risen up against me, and injustice has lied to itself.", ar: "لا تسلمني إلى أيدي مضايقي، لأنه قد قام على شهود زور، وكذبوا علي ظلما." }, label: { en: "20", ar: "20" } },
      { kind: 'psalm', text: { en: "I believe that I shall see the goodness of the Lord in the land of the living.", ar: "وأنا أؤمن أنى أعاين خيرات الرب في أرض الأحياء." }, label: { en: "21", ar: "21" } },
      { kind: 'psalm', text: { en: "Wait for the Lord: be of good cheer and let your heart be strengthened: and wait for the Lord.", ar: "انتظر الربّ، تقوَّ وليتشدد قلبك وانتظر الرب." }, label: { en: "22", ar: "22" } },
      { kind: 'heading', text: { en: "Psalm 62", ar: "مزمور 62" } },
      { kind: 'psalm', text: { en: "O God, my God, I will rise up early unto You; for my soul has thirsted for You.", ar: "يا الله إلهي إليك أبكر، عطشت إليك نفسي." }, label: { en: "1", ar: "1" } },
      { kind: 'psalm', text: { en: "To make my flesh blossom for You, in a barren land and a trackless and dry place.", ar: "يشتاق إليك جسدي، في أرض مقفرة وموضع غير مسلوك ومكان بلا ماء." }, label: { en: "2", ar: "2" } },
      { kind: 'psalm', text: { en: "So I have appeared before You in the Holy, to see Your power and Your glory.", ar: "هكذا ظهرت لك في القدس، لأرى قوّتك ومجدك." }, label: { en: "3", ar: "3" } },
      { kind: 'psalm', text: { en: "For Your mercy is chosen more than life.", ar: "لان رحمتك أفضل من الحياة." }, label: { en: "4", ar: "4" } },
      { kind: 'psalm', text: { en: "My lips shall praise You.", ar: "شفتاي تسبحانِك." }, label: { en: "5", ar: "5" } },
      { kind: 'psalm', text: { en: "So I will bless You during my life: I will lift up my hands in Your name.", ar: "لذلك أباركك في حياتي، وباسمك أرفع يدي." }, label: { en: "6", ar: "6" } },
      { kind: 'psalm', text: { en: "My soul shall be filled as with marrow and fatness.", ar: "فتشبع نفسي كما من شحم ودسم." }, label: { en: "7", ar: "7" } },
      { kind: 'psalm', text: { en: "And lips of joy shall praise Your name.", ar: "بشفاه الابتهاج نبارك اسمك." }, label: { en: "8", ar: "8" } },
      { kind: 'psalm', text: { en: "I have remembered You on my bed: in the time of early morning I have usually meditated on You.", ar: "كنت أذكرك على فراشي، وفى أوقات الأسحار كنت أرتل لك." }, label: { en: "9", ar: "9" } },
      { kind: 'psalm', text: { en: "For You have become unto me a helper, and under the shadow of Your wings I shall rejoice.", ar: "لأنك صرت لي عونا، وبظل جناحيك أبتهج." }, label: { en: "10", ar: "10" } },
      { kind: 'psalm', text: { en: "My soul has kept very close behind You: Your right hand has upheld me.", ar: "التحقت نفسي وراءك، ويمينك عضدتني." }, label: { en: "11", ar: "11" } },
      { kind: 'psalm', text: { en: "But they vainly sought after my soul; they shall go into the lowest parts of the earth.", ar: "أما الذين طلبوا نفسي للهلاك، فيدخلون في أسافل الأرض." }, label: { en: "12", ar: "12" } },
      { kind: 'psalm', text: { en: "They shall be delivered up to the hand of the sword; they shall be portions for foxes.", ar: "ويُدفعون إلى يد السيف، ويكونون أنصبة للثعالب." }, label: { en: "13", ar: "13" } },
      { kind: 'psalm', text: { en: "But the king shall rejoice in God; everyone who swears by him shall be proud.", ar: "أما الملك فيفرح بالله، ويفتخر كل من يحلف به." }, label: { en: "14", ar: "14" } },
      { kind: 'psalm', text: { en: "For the mouths of those who speak unjust things shall be shut.", ar: "لأن أفواه المتكلمين بالظلم تُسَدُّ." }, label: { en: "15", ar: "15" } },
      { kind: 'heading', text: { en: "Psalm 66", ar: "مزمور 66" } },
      { kind: 'psalm', text: { en: "God shall pity us, and bless us; and reveal His face upon us and have mercy on us.", ar: "ليتراءف الله علينا ويباركنا، وليظهر وجهه علينا ويرحمنا." }, label: { en: "1", ar: "1" } },
      { kind: 'psalm', text: { en: "That Your way may be known on the earth, Your salvation among all nations.", ar: "لتعرَف في الأرض طريقك، وفى جميع الأمم خلاصك." }, label: { en: "2", ar: "2" } },
      { kind: 'psalm', text: { en: "Let the peoples, O God, give praise to You; let all the peoples give praise to You.", ar: "فلتعترف لك الشعوب يا الله، فلتعترف لك الشعوب كلها." }, label: { en: "3", ar: "3" } },
      { kind: 'psalm', text: { en: "Let the nations rejoice and exult, for You will judge peoples in equity, and guide nations on the earth.", ar: "لتفرح الأمم وتبتهج، لأنك تحكم في الشعوب بالاستقامة، وتهدى الأمم في الأرض." }, label: { en: "4", ar: "4" } },
      { kind: 'psalm', text: { en: "Let the peoples, O God, give praise to You; let all the peoples give praise to You.", ar: "فلتعترف لك الشعوب يا الله، فلتعترف لك الشعوب جميعا." }, label: { en: "5", ar: "5" } },
      { kind: 'psalm', text: { en: "The earth has yielded its fruit. God, our God, shall bless us.", ar: "الأرض أعطت ثمرتها، فليباركنا الله إلهنا." }, label: { en: "6", ar: "6" } },
      { kind: 'psalm', text: { en: "God shall bless us; and all the ends of the earth shall fear Him.", ar: "ليباركنا الله، فلتخشه جميع أقطار الأرض." }, label: { en: "7", ar: "7" } },
      { kind: 'heading', text: { en: "Psalm 69", ar: "مزمور 69" } },
      { kind: 'psalm', text: { en: "O God, be mindful of my help; make haste, O Lord, to help me.", ar: "اللهم التفت إلى معونتي، يا رب أسرع وأعنى." }, label: { en: "1", ar: "1" } },
      { kind: 'psalm', text: { en: "Let them be ashamed and be scorned, those who seek my soul: let them be turned backward and put to shame, those who wish to do evil unto me.", ar: "ليَخزَ ويخجل طالبو نفسي، وليرتد إلى خلف ويخجل الذين يبتغون لي الشر." }, label: { en: "2", ar: "2" } },
      { kind: 'psalm', text: { en: "Let those who say to me, \"Aha, aha,\" be turned back in shame immediately.", ar: "وليرجع بالخزي سريعا القائلون لي: نِعِمَّا نِعِمَّا." }, label: { en: "3", ar: "3" } },
      { kind: 'psalm', text: { en: "Let all who seek You exult and be glad in You: and let those who love Your salvation say continually, \"Let the Lord be magnified.\"", ar: "وليبتهج ويفرح بك جميع الذين يلتمسونك، وليقل في كل حين محبو خلاصك: فليتعظم الرب." }, label: { en: "4", ar: "4" } },
      { kind: 'psalm', text: { en: "But I am poor and weak; O God, help me.", ar: "وأما أنا فمسكين وفقير، اللهم أعنى." }, label: { en: "5", ar: "5" } },
      { kind: 'psalm', text: { en: "You are my Helper and Savior, O Lord, do not delay. Alleluia.", ar: "أنت معيني ومخلصي يا رب فلا تبطئ.هلليلويا." }, label: { en: "6", ar: "6" } },
      { kind: 'heading', text: { en: "Psalm 112", ar: "مزمور 112" } },
      { kind: 'psalm', text: { en: "Praise the Lord, O you servants, praise the name of the Lord.", ar: "سبحوا الرب أيها الفتيان، سبحوا اسم الرب." }, label: { en: "1", ar: "1" } },
      { kind: 'psalm', text: { en: "Let the name of the Lord be blessed from now and forever.", ar: "ليكن اسم الرب مباركا من الآن وإلى الأبد." }, label: { en: "2", ar: "2" } },
      { kind: 'psalm', text: { en: "From the risings of the sun to its settings, praise the name of the Lord.", ar: "من مشارق الشمس إلى مغاربها باركوا اسم الرب." }, label: { en: "3", ar: "3" } },
      { kind: 'psalm', text: { en: "The Lord is high above all the nations; upon the heavens is His glory.", ar: "الرب عالٍ على كل الأمم، فوق السموات مجده." }, label: { en: "4", ar: "4" } },
      { kind: 'psalm', text: { en: "Who is like the Lord our God? Who dwells in the high places, and looks upon the low things in heaven and on the earth.", ar: "من مثل الرب إلهنا؟!‍ الساكن في الأعالي، الناظِر إلى المتواضعين في السماء وعلى الأرض." }, label: { en: "5", ar: "5" } },
      { kind: 'psalm', text: { en: "Who lifts up a poor person from the earth, and raises up a needy person from the ash heap; to seat him with the princes, even with the princes of his people.", ar: "المقيم المسكين من التراب، الرافع البائس من المِزْبَلة لكي يُجلسه مع رؤساء شعبه." }, label: { en: "6", ar: "6" } },
      { kind: 'psalm', text: { en: "Who makes a barren woman in a house, rejoicing as a mother of children.", ar: "الذي يجعل العاقرَ ساكنة في بيت، أم أولادٍ فرحة." }, label: { en: "7", ar: "7" } },
      { kind: 'heading', text: { en: "Psalm 142", ar: "مزمور 142" } },
      { kind: 'psalm', text: { en: "O Lord, hear my prayer.", ar: "يا رب اسمع صلاتي." }, label: { en: "1", ar: "1" } },
      { kind: 'psalm', text: { en: "Give ear to my supplication in Your truth.", ar: "أنصت إلى طلبتي بحقك." }, label: { en: "2", ar: "2" } },
      { kind: 'psalm', text: { en: "Hearken to me in Your justice.", ar: "استجب لي بعدلك." }, label: { en: "3", ar: "3" } },
      { kind: 'psalm', text: { en: "And do not enter into judgement with Your servant, for in Your sight no one living shall be justified.", ar: "ولا تدخل في المحاكمة مع عبدك، فإنه لن يتزكى قدامك كل حي." }, label: { en: "4", ar: "4" } },
      { kind: 'psalm', text: { en: "For the enemy has persecuted my soul; he has humbled my life down to the ground.", ar: "لأن العدو قد اضطهد نفسي، وأذل في الأرض حياتي." }, label: { en: "5", ar: "5" } },
      { kind: 'psalm', text: { en: "He has made me to sit in darkness, as those who have been long dead. Therefore, my spirit grieves in me; my heart is troubled within me.", ar: "أجلسَني في الظلمات مثل الموتى منذ الدهر، أضجر في روحي، اضطرب في قلبي." }, label: { en: "6", ar: "6" } },
      { kind: 'psalm', text: { en: "I remembered the days of old; and I meditated on all Your doings: I meditated on the works of Your hands.", ar: "تذكرت الأيام الأولى ولهجت في كل أعمالك، وفى صنائع يديك كنت أتأمل." }, label: { en: "7", ar: "7" } },
      { kind: 'psalm', text: { en: "I spread forth my hands unto You; my soul is toward You as a dry land.", ar: "بسطت إليك يدي، صارت نفسي لك مثل أرض بلا ماء." }, label: { en: "8", ar: "8" } },
      { kind: 'psalm', text: { en: "Hear me quickly, O Lord, for my spirit has failed.", ar: "استجب لي يا رب عاجلا، فقد فنيت روحي." }, label: { en: "9", ar: "9" } },
      { kind: 'psalm', text: { en: "Do not turn away Your face from me, or I will be like those who go down to the pit.", ar: "لا تحجب وجهك عني، فأشابه الهابطين في الجب." }, label: { en: "10", ar: "10" } },
      { kind: 'psalm', text: { en: "Let me hear Your mercy in the morning, for in You do I hope.", ar: "فلأسمع في الغدوات رحمتك، فإني عليك توكلت." }, label: { en: "11", ar: "11" } },
      { kind: 'psalm', text: { en: "Make known to me, O Lord, the way in which I should walk, for I have lifted up my soul to You.", ar: "عرفني يا رب الطريق التي أسلك فيها، لأني إليك رفعت نفسي." }, label: { en: "12", ar: "12" } },
      { kind: 'psalm', text: { en: "Deliver me from my enemies, O Lord; for I have fled to You.", ar: "أنقذني من أعدائي يا رب، فإني لجأت إليك." }, label: { en: "13", ar: "13" } },
      { kind: 'psalm', text: { en: "Teach me to do Your will, for You are my God.", ar: "علمني أن أصنع مشيئتك، لأنك أنت هو إلهي." }, label: { en: "14", ar: "14" } },
      { kind: 'psalm', text: { en: "Let Your Holy Spirit guide me in the straight way. You shall revive me, O Lord, for Your name's sake.", ar: "روحك القدوس فليهدني إلى الاستقامة، من أجل اسمك يا رب تحييني." }, label: { en: "15", ar: "15" } },
      { kind: 'psalm', text: { en: "In Your righteousness You shall bring my soul out of affliction. And in Your mercy You will wipe out my enemies.", ar: "بحقك تخرج من الشدة نفسي، وبرحمتك تستأصل أعدائي." }, label: { en: "16", ar: "16" } },
      { kind: 'psalm', text: { en: "And destroy all who afflict my soul; for I am Your servant.", ar: "وتهلك جميع مضايقي نفسي، لأني أنا هو عبدك أنا." }, label: { en: "17", ar: "17" } },
      { kind: 'rubric', text: { en: "Glory to You, O our God. Holy, holy, holy. A psalm of David. A reading from the Gospel according to our teacher Saint John the Evangelist. May his blessings be with us all. Amen.", ar: "Glory to You, O our God. Holy, holy, holy. A psalm of David. A reading from the Gospel according to our teacher Saint John the Evangelist. May his blessings be with us all. Amen." } },
      { kind: 'gospel', text: { en: "John 1:1-17", ar: "يوحنا 1:1-17" }, label: { en: "Gospel", ar: "الإنجيل" } },
      { kind: 'heading', text: { en: "Litanies", ar: "الطلبات" } },
      { kind: 'litany', text: { en: "We worship You, O Christ, with Your Good Father and the Holy Spirit, for You have come and saved us. Lord have mercy.", ar: "أيها النور الحقيقي الذي يضئ لكل إنسان آت إلى العالم، أتيت إلى العالم بمحبتك للبشر، وكل الخليقة تهللت بمجيئك. خلصت أبانا آدم من الغواية، وعتقت أمنا حواء من طلقات الموت، وأعطيتنا روح البنوة، نسبحك ونباركك قائلين: (" } },
      { kind: 'litany', text: { en: "A crown of blessing is the First Hour, which You grant to us, O Christ our God, for the forgiveness of our sins. Lord have mercy.", ar: "ذوكصابتري" } },
      { kind: 'litany', text: { en: "O Lord, Who at the First Hour did send Your Holy Spirit upon Your apostles, take not that Spirit from us, O Good One, but renew Him within us. Lord have mercy.", ar: "كيه إيو كي آجيو ابنيفماتي" } },
      { kind: 'litany', text: { en: "Create in me a clean heart, O God, and renew a steadfast spirit within me. Cast me not away from Your presence, and take not Your Holy Spirit from me.", ar: "المجد للآب والابن والروح القدس" } },
      { kind: 'litany', text: { en: "Blessed is the Lord God, for He has visited and redeemed His people. Lord have mercy.", ar: "إذا ما دخل إلينا وقت الصباح أيها المسيح إلهنا النور الحقيقي، فلتشرق فينا الحواس المضيئة والأفكار النورانية. ولا تغطينا ظلمة الآلام، لكي نسبحك عقليا مع داود قائلين: \"سبقت عيناي وقت السحر لأتلو في جميع أقوالك\". اسمع أصواتنا كعظيم رحمتك، ونجنا أيها الرب إلهنا بتحننك. (" } },
      { kind: 'litany', text: { en: "", ar: "كي نين" } },
      { kind: 'litany', text: { en: "", ar: "، كي آ إي، كي ايستوس إي أوناس تون إي أونون آمين" } },
      { kind: 'litany', text: { en: "", ar: "الآن وكل أوان وإلى دهر الداهرين آمين" } },
      { kind: 'litany', text: { en: "", ar: "أنت هي أم النور المكرمة، من مشارق الشمس إلى مغاربها يقدمون لك تمجيدات يا والدة الإله السماء الثانية، لأنك أنت هي الزهرة النيرة غير المتغيرة والأم الباقية عذراء، لأن الآب اختارك، والروح القدس ظللك، والابن تنازل وتجسد منك. فاسأليه أن يعطى الخلاص للعالم الذي خلقه، وأن ينجيَّه من التجارب. نسبحه تسبيحا جديدا ونباركه الآن وكل أوان وإلى الأبد. أمين." } },
      { kind: 'litany', text: { en: "", ar: "فلنسبح مع الملائكة قائلين: المجد لله في الأعالي وعلى الأرض السلام وفى الناس المسرة. نسبحك. نباركك. نخدمك. نسجد لك. نعترف لك. ننطق بمجدك. نشكرك من أجل عظم مجدك، أيها الرب المالك على السموات، الله الآب ضابط الكل، والرب الابن الواحد الوحيد يسوع المسيح، والروح القدس." } },
      { kind: 'litany', text: { en: "", ar: "أيها الرب الإله، حمل الله، ابن الآب، رافع خطية العالم، ارحمنا. يا حامل خطية العالم، اقبل طلباتنا إليك. أيها الجالس عن يمين أبيه، ارحمنا. أنت وحدك القدوس. أنت وحدك العالي يا ربى يسوع المسيح والروح القدس. مجدا لله الآب أمين." } },
      { kind: 'litany', text: { en: "", ar: "أباركك كل يوم، وأسبح اسمك القدوس إلى الأبد. وإلى أبد الأبد. أمين. منذ الليل روحي تبكر إليك يا إلهي، لأن أوامرك هي نور على الأرض. كنت أتلو في طرقك، لأنك صرت لي معينا. باكرا يا رب تسمع صوتي، بالغداة أقف أمامك وتراني." } },
      { kind: 'litany', text: { en: "", ar: "قدوس، قدوس، قدوس، رب الصباؤوت. السماء والأرض مملوءتان من مجدك وكرامتك. ارحمنا يا الله الآب ضابط الكل. أيها الثالوث القدوس ارحمنا. أيها الرب إله القوات كن معنا، لأنه ليس لنا معين في شدائدنا وضيقاتنا سواك." } },
      { kind: 'litany', text: { en: "", ar: "حل واغفر واصفح لنا يا الله عن سيئاتنا، التي صنعناها بإرادتنا والتي صنعناها بغير إرادتنا، التي فعلناها بمعرفة والتي فعلناها بغير معرفة، الخفية والظاهرة. يا رب اغفرها لنا، من أجل اسمك القدوس الذي دعي علينا. كرحمتك يا رب وليس كخطايانا." } },
      { kind: 'litany', text: { en: "", ar: "واجعلنا مستحقين أن نقول بشكر: أبانا الذي في السموات.." } },
      { kind: 'litany', text: { en: "", ar: "ارحمنا يا الله ثم ارحمنا. يا من في كل وقت وكل ساعة، في السماء وعلى الأرض، مسجود له وممجد. المسيح إلهنا الصالح، الطويل الروح، الكثير الرحمة، الجزيل التحنن، الذي يحب الصديقين ويرحم الخطاة الذين أولهم أنا. الذي لا يشاء موت الخاطئ مثل ما يرجع ويحيا. الداعي الكل إلى الخلاص لأجل الموعد بالخيرات المنتظرة." } },
      { kind: 'litany', text: { en: "", ar: "يا رب اقبل منا في هذه الساعة وكل ساعة طلباتنا. سهل حياتنا، وأرشدنا إلى العمل بوصاياك. قدس أرواحنا. طهر أجسامنا. قوم أفكارنا. نق نياتنا. اشف أمراضنا واغفر خطايانا. ونجنا من كل حزن رديء ووجع قلب. أحطنا بملائكتك القديسين، لكي نكون بمعسكرهم محفوظين ومرشدين، لنصل إلى اتحاد الإيمان وإلى معرفة مجدك غير المحسوس وغير المحدود، فإنك مبارك إلى الأبد. أمين." } },
      { kind: 'litany', text: { en: "", ar: "اللهم اجعلنا مستحقين أن نقول بشكر:" } },
      { kind: 'litany', text: { en: "", ar: "أبانا الذي في السموات" } },
      { kind: 'heading', text: { en: "The Lord's Prayer", ar: "الصلاة الربانية" } },
      { kind: 'prayer', text: { en: "The Lord's Prayer", ar: "الصلاة الربانية" } },
      { kind: 'prayer', text: { en: "Make us worthy to say with thankfulness:", ar: "اللهم اجعلنا مستحقين أن نقول بشكر:" } },
      { kind: 'prayer', text: { en: "Our Father Who art in heaven, hallowed be Thy Name. Thy kingdom come. Thy will be done on earth as it is in heaven. Give us this day our daily bread. And forgive us our trespasses, as we forgive those who trespass against us. And lead us not into temptation, but deliver us from the evil one. In Christ Jesus our Lord. For Thine is the kingdom, the power and the glory, forever. Amen.", ar: "أبانا الذي في السموات. ليتقدس اسمك. ليأت ملكوتك. لتكن مشيئتك. كما في السماء كذلك على الأرض. خبزنا الذي للغد أعطنا اليوم. وأغفر لنا ذنوبنا كما نغفر نحن أيضا للمذنبين إلينا. ولا تدخلنا في تجربة. لكن نجنا من الشرير. بالمسيح يسوع ربنا لأن لك الملك والقوة والمجد إلى الأبد. آمين." } },
      { kind: 'heading', text: { en: "Concluding Prayer", ar: "الختام" } },
      { kind: 'prayer', text: { en: "O Lord, God of hosts, who exists before all ages and endures forever, who created the sun for the light of day, and the night for the rest of all mankind: we thank You, O King of the ages, for You have brought us through this night in peace and brought us to the beginning of the day.", ar: "أيها الرب إله القوات، الكائن قبل الدهور والدائم إلى الأبد، الذي خلق الشمس لضياء النهار، والليل راحة لكل البشر، نشكرك يا ملك الدهور لأنك أجزتنا هذا الليل بسلام وأتيت بنا إلى مبدأ النهار." } },
      { kind: 'prayer', text: { en: "Therefore we ask You, our King, the King of all ages: let the light of Your face shine upon us, and let the light of Your divine knowledge illumine us. Grant, our Master, that we may be children of the light and children of the day, that we may pass this day in righteousness, purity, and good order, and complete the rest of the days of our life without stumbling; through the grace, compassion, and love of mankind of Your only-begotten Son, Jesus Christ, and the gift of Your Holy Spirit, now and at all times and forever. Amen.", ar: "من أجل هذا نسأل يا ملكنا ملك الدهور، ليشرق لنا نور وجهك، وليضيء علينا نور علمك الإلهي. واجعلنا يا سيدنا أن نكون بنى النور وبني النهار، لكي نجوز هذا اليوم ببر وطهارة وتدبير حسن، لنكمل بقية أيام حياتنا بلا عثرة. بالنعمة والرأفة ومحبة البشر اللواتي لابنك الوحيد يسوع المسيح، وموهبة روحك القدوس. الآن وكل أوان وإلى الأبد. أمين." } },
      { kind: 'prayer', text: { en: "O Sender of the light, who causes it to go forth, who makes His sun rise upon the righteous and the wicked, who made the light that shines upon the whole world: enlighten our minds, our hearts, and our understanding, O Master of all. Grant us to please You this present day; guard us from every evil thing, from every sin, and from every adverse power; through Jesus Christ our Lord, with whom You are blessed, together with the life-giving Holy Spirit who is co-essential with You, now and at all times and unto the age of ages. Amen.", ar: "أيها الباعث النور فينطلق، المشرق شمسه على الأبرار والأشرار، الذي صنع النور الذي يضئ على المسكونة، أنر عقولنا وقلوبنا وأفهامنا يا سيد الكل. هب لنا في هذا اليوم الحاضر أن نرضيك فيه. واحرسنا من كل شيء رديء ومن كل خطيئة، ومن كل قوة مضادة بالمسيح يسوع ربنا. هذا الذي أنت مبارك معه مع الروح القدس المحيى المساوي لك، الآن وكل أوان وإلى دهر الدهور. أمين." } }
    ],
  }
];
